const Booking = require("../models/Booking");
const Flight = require("../models/Flight");

// =====================================================
// GENERATE UNIQUE BOOKING ID
// =====================================================

const generateBookingId = () => {
  return (
    "ST" +
    Math.floor(
      100000 +
        Math.random() * 900000
    )
  );
};


// =====================================================
// GET UNIQUE BOOKING ID
// =====================================================

const getUniqueBookingId = async () => {

  let bookingId;
  let exists = true;

  while (exists) {

    bookingId =
      generateBookingId();

    exists =
      await Booking.exists({
        bookingId,
      });

  }

  return bookingId;
};


// =====================================================
// SAFE NUMBER
// =====================================================

const numberValue = (value) => {

  const number =
    Number(value);

  return Number.isFinite(number)
    ? number
    : 0;
};


// =====================================================
// CREATE BOOKING
// POST /api/bookings
// =====================================================

const createBooking = async (
  req,
  res
) => {

  let bookedFlightId = null;
  let bookedPNR = null;
  let generatedBookingId = null;

  try {

    console.log(
      "========================================"
    );

    console.log(
      "CREATE BOOKING REQUEST"
    );

    console.log(
      JSON.stringify(
        req.body,
        null,
        2
      )
    );

    console.log(
      "========================================"
    );


    // =================================================
    // REQUEST DATA
    // =================================================

    // const {

    //   passenger,

    //   passengers,

    //   flight,

    //   flightId,

    //   seat,

    //   seats,

    //   seatPrice,

    //   meal,

    //   meals,

    //   baggage,

    //   baggages,

    //   paymentMethod,

    //   paymentVerified,

    //   discount,

    //   adults,

    //   children,

    //   infants,

    //   fareRole,

    //   userRole,

    // } = req.body;





    const {
  passenger,
  passengers,
  flight,
  flightId,
  seat,
  seats,
  seatPrice,
  meal,
  meals,
  baggage,
  baggages,
  paymentMethod,
  paymentVerified,
  paymentId,
  orderId,
  discount,
  adults,
  children,
  infants,
  fareRole,
  userRole,
} = req.body;


    // =================================================
    // USER ROLE
    // =================================================
    //
    // FINAL RULE:
    //
    // ADMIN
    // -> Payment NOT required
    // -> Direct booking confirmation
    //
    // AGENT
    // -> Payment required
    //
    // CUSTOMER
    // -> Payment required
    //
    // Backend authenticated role gets priority.
    // If authentication middleware is not available,
    // frontend role is used as fallback.
    //

    const normalizedUserRole =
      String(
        req.user?.role ||
        userRole ||
        fareRole ||
        "customer"
      )
        .trim()
        .toLowerCase();


    const isAdmin =
      normalizedUserRole === "admin";


    const isAgent =
      normalizedUserRole === "agent";


    const isCustomer =
      normalizedUserRole === "customer";


    console.log(
      "USER ROLE:",
      normalizedUserRole
    );


    // =================================================
    // PAYMENT VERIFICATION
    // =================================================
    //
    // IMPORTANT:
    //
    // Customer + Agent MUST have verified payment.
    //
    // Do NOT send paymentVerified=true from the
    // browser unless your payment gateway has actually
    // verified the transaction.
    //

    const verifiedPayment =
      paymentVerified === true ||
      paymentVerified === "true";


    // =================================================
    // PAYMENT GATE
    // =================================================
    //
    // ADMIN -> bypass payment
    //
    // AGENT/CUSTOMER -> payment required
    //

    if (
      !isAdmin &&
      !verifiedPayment
    ) {

      return res.status(402).json({

        success: false,

        paymentRequired: true,

        paymentVerified: false,

        userRole:
          normalizedUserRole,

        message:
          "Payment is required before the ticket can be confirmed.",

      });

    }


    // =================================================
    // PASSENGERS
    // =================================================

    let passengerList = [];


    // New system
    if (
      Array.isArray(passengers) &&
      passengers.length > 0
    ) {

      passengerList =
        passengers;

    }


    // Old system compatibility
    else if (passenger) {

      passengerList = [

        {
          ...passenger,

          type:
            passenger.type ||
            "Adult",
        },

      ];

    }


    // =================================================
    // PASSENGER VALIDATION
    // =================================================

    if (
      !Array.isArray(
        passengerList
      ) ||
      passengerList.length === 0
    ) {

      return res.status(400).json({

        success: false,

        message:
          "At least one passenger is required.",

      });

    }


    // =================================================
    // VALIDATE EACH PASSENGER
    // =================================================

    for (
      let i = 0;
      i < passengerList.length;
      i++
    ) {

      const currentPassenger =
        passengerList[i];


      if (
        !currentPassenger.firstName ||
        !String(
          currentPassenger.firstName
        ).trim()
      ) {

        return res.status(400).json({

          success: false,

          message:
            `First name is required for passenger ${i + 1}.`,

        });

      }


      if (
        !currentPassenger.lastName ||
        !String(
          currentPassenger.lastName
        ).trim()
      ) {

        return res.status(400).json({

          success: false,

          message:
            `Last name is required for passenger ${i + 1}.`,

        });

      }


      // Passenger type
      if (
        ![
          "Adult",
          "Child",
          "Infant",
        ].includes(
          currentPassenger.type
        )
      ) {

        currentPassenger.type =
          "Adult";

      }

    }


    // =================================================
    // FLIGHT VALIDATION
    // =================================================

    if (
      !flight &&
      !flightId
    ) {

      return res.status(400).json({

        success: false,

        message:
          "Flight details are required.",

      });

    }


    // =================================================
    // FIND FLIGHT ID
    // =================================================

    const requestedFlightId =
      flightId ||
      flight?._id ||
      flight?.id ||
      flight?.flightId;


    if (!requestedFlightId) {

      return res.status(400).json({

        success: false,

        message:
          "Flight ID is missing.",

      });

    }


    // =================================================
    // FIND REAL DATABASE FLIGHT
    // =================================================

    let dbFlight = null;


    try {

      dbFlight =
        await Flight.findById(
          requestedFlightId
        );

    } catch (error) {

      console.log(
        "Invalid Flight ID:",
        requestedFlightId
      );

    }


    // =================================================
    // FALLBACK - FIND BY FLIGHT NUMBER
    // =================================================

    if (
      !dbFlight &&
      flight?.flightNo
    ) {

      const flightNo =
        String(
          flight.flightNo
        )
          .trim()
          .toUpperCase();


      dbFlight =
        await Flight.findOne({
          flightNo,
        });

    }


    // =================================================
    // FLIGHT NOT FOUND
    // =================================================

    if (!dbFlight) {

      return res.status(404).json({

        success: false,

        message:
          "Flight not found. Please select the flight again.",

      });

    }


    console.log(
      "========================================"
    );

    console.log(
      "DATABASE FLIGHT FOUND"
    );

    console.log(
      "Flight ID:",
      dbFlight._id
    );

    console.log(
      "Flight:",
      dbFlight.flightNo
    );

    console.log(
      "Airline:",
      dbFlight.airline
    );

    console.log(
      "USER ROLE:",
      normalizedUserRole
    );

    console.log(
      "PAYMENT VERIFIED:",
      verifiedPayment
    );

    console.log(
      "========================================"
    );


    // =================================================
    // CHECK AVAILABLE TICKETS / PNR
    // =================================================

    if (
      !Array.isArray(
        dbFlight.tickets
      ) ||
      dbFlight.tickets.length === 0
    ) {

      return res.status(409).json({

        success: false,

        message:
          "No ticket / PNR is available for this flight.",

      });

    }


    // =================================================
    // FIND ONE AVAILABLE ADMIN PNR
    // =================================================

    const availableTicket =
      dbFlight.tickets.find(
        (ticket) =>
          ticket.status ===
          "Available"
      );


    if (!availableTicket) {

      return res.status(409).json({

        success: false,

        message:
          "No ticket / PNR is available for this flight.",

      });

    }


    // =================================================
    // ADMIN ORIGINAL PNR
    // =================================================

    const selectedPNR =
      String(
        availableTicket.pnr
      )
        .trim()
        .toUpperCase();


    console.log(
      "ADMIN ORIGINAL PNR:",
      selectedPNR
    );


    // =================================================
    // BOOKING ID
    // =================================================

    const bookingId =
      await getUniqueBookingId();


    generatedBookingId =
      bookingId;


    // =================================================
    // PASSENGER COUNTS
    // =================================================

    const adultCount =
      numberValue(
        adults
      ) ||
      passengerList.filter(
        (item) =>
          item.type === "Adult"
      ).length;


    const childCount =
      numberValue(
        children
      ) ||
      passengerList.filter(
        (item) =>
          item.type === "Child"
      ).length;


    const infantCount =
      numberValue(
        infants
      ) ||
      passengerList.filter(
        (item) =>
          item.type === "Infant"
      ).length;


    const totalPassengerCount =
      passengerList.length;


    // =================================================
    // PRICE
    // =================================================

    const normalizedFareRole =
      normalizedUserRole === "agent"
        ? "agent"
        : "customer";


    const isAgentBooking =
      normalizedFareRole ===
      "agent";


    const customerAdultFare =
      numberValue(
        dbFlight.adultFare ??
        dbFlight.finalPrice
      );


    const agentAdultFare =
      numberValue(
        dbFlight.agentAdultFare
      );


    const customerChildFare =
      numberValue(
        dbFlight.childFare ??
        customerAdultFare
      );


    const agentChildFare =
      numberValue(
        dbFlight.agentChildFare ??
        agentAdultFare
      );


    const customerInfantFare =
      numberValue(
        dbFlight.infantFare
      );


    const agentInfantFare =
      numberValue(
        dbFlight.agentInfantFare ??
        agentAdultFare
      );


    const selectedAdultFare =
      isAgentBooking
        ? agentAdultFare
        : customerAdultFare;


    const selectedChildFare =
      isAgentBooking
        ? agentChildFare
        : customerChildFare;


    const selectedInfantFare =
      isAgentBooking
        ? agentInfantFare
        : customerInfantFare;


    // =================================================
    // PASSENGER FARE
    // =================================================

    const flightFare =
      selectedAdultFare *
        Number(adults || 0) +

      selectedChildFare *
        Number(children || 0) +

      selectedInfantFare *
        Number(infants || 0);


    // =================================================
    // SEATS
    // =================================================

    let seatList = [];


    if (
      Array.isArray(seats)
    ) {

      seatList =
        seats;

    }

    else if (seat) {

      seatList = [

        {

          seatNumber:
            seat,

          price:
            numberValue(
              seatPrice
            ),

        },

      ];

    }


    // =================================================
    // NORMALIZE SEATS
    // =================================================

    const normalizedSeats =
      seatList
        .filter(Boolean)
        .map(
          (item, index) => {

            const passengerAtIndex =
              passengerList[index];


            const passengerName =
              passengerAtIndex
                ? `${passengerAtIndex.firstName || ""} ${passengerAtIndex.lastName || ""}`.trim()
                : "";


            return {

              passengerId:
                passengerAtIndex?._id ||
                null,

              passengerName,

              seatNumber:
                String(
                  item.seatNumber ||
                  item.seat ||
                  ""
                )
                  .trim()
                  .toUpperCase(),

              price:
                numberValue(
                  item.price
                ),

            };

          }
        )
        .filter(
          (item) =>
            item.seatNumber
        );


    // =================================================
    // SEAT FARE
    // =================================================

    const calculatedSeatFare =
      normalizedSeats.reduce(
        (
          total,
          item
        ) =>
          total +
          numberValue(
            item.price
          ),

        0
      );


    const finalSeatFare =
      calculatedSeatFare ||
      numberValue(
        seatPrice
      );

          // =================================================
    // MEALS
    // =================================================

    let mealList = [];

    if (Array.isArray(meals)) {
      mealList = meals;
    } else if (meal) {
      mealList = [meal];
    }


    // =================================================
    // NORMALIZE MEALS
    // =================================================

    const normalizedMeals =
      mealList
        .filter(Boolean)
        .map((item, index) => {

          const passengerAtIndex =
            passengerList[index];

          const passengerName =
            passengerAtIndex
              ? `${passengerAtIndex.firstName || ""} ${passengerAtIndex.lastName || ""}`.trim()
              : "";

          return {
            passengerId:
              passengerAtIndex?._id || null,

            passengerName,

            name:
              item.name ||
              "No Meal",

            price:
              numberValue(
                item.price
              ),
          };

        });


    // =================================================
    // MEAL FARE
    // =================================================

    const mealFare =
      normalizedMeals.reduce(
        (total, item) =>
          total +
          numberValue(item.price),
        0
      );


    // =================================================
    // BAGGAGE
    // =================================================

    let baggageList = [];

    if (Array.isArray(baggages)) {
      baggageList = baggages;
    } else if (baggage) {
      baggageList = [baggage];
    }


    // =================================================
    // NORMALIZE BAGGAGE
    // =================================================

    const normalizedBaggages =
      baggageList
        .filter(Boolean)
        .map((item, index) => {

          const passengerAtIndex =
            passengerList[index];

          const passengerName =
            passengerAtIndex
              ? `${passengerAtIndex.firstName || ""} ${passengerAtIndex.lastName || ""}`.trim()
              : "";

          return {

            passengerId:
              passengerAtIndex?._id || null,

            passengerName,

            weight:
              item.weight ||
              "15 KG (Included)",

            price:
              numberValue(
                item.price
              ),

          };

        });


    // =================================================
    // BAGGAGE FARE
    // =================================================

    const baggageFare =
      normalizedBaggages.reduce(
        (total, item) =>
          total +
          numberValue(item.price),
        0
      );


    // =================================================
    // TAXES
    // =================================================

    const taxes = 0;


    // =================================================
    // CONVENIENCE FEE
    // =================================================

    const convenienceFee = 0;


    // =================================================
    // DISCOUNT
    // =================================================

    const discountAmount =
      Math.max(
        0,
        numberValue(discount)
      );


    // =================================================
    // FINAL TOTAL
    // =================================================

    const calculatedTotal =
      flightFare +
      finalSeatFare +
      mealFare +
      baggageFare +
      taxes +
      convenienceFee -
      discountAmount;


    // =================================================
    // TOTAL VALIDATION
    // =================================================

    if (calculatedTotal < 0) {

      return res.status(400).json({

        success: false,

        message:
          "Invalid booking total.",

      });

    }


    // =================================================
    // PRICE LOG
    // =================================================

    console.log(
      "========================================"
    );

    console.log(
      "FINAL PRICE CALCULATION"
    );

    console.log(
      "Passengers:",
      totalPassengerCount
    );

    console.log(
      "Adults:",
      adultCount
    );

    console.log(
      "Children:",
      childCount
    );

    console.log(
      "Infants:",
      infantCount
    );

    console.log(
      "Fare Role:",
      normalizedFareRole
    );

    console.log(
      "Flight Fare:",
      flightFare
    );

    console.log(
      "Seat Fare:",
      finalSeatFare
    );

    console.log(
      "Meal Fare:",
      mealFare
    );

    console.log(
      "Baggage Fare:",
      baggageFare
    );

    console.log(
      "Discount:",
      discountAmount
    );

    console.log(
      "FINAL TOTAL:",
      calculatedTotal
    );

    console.log(
      "========================================"
    );


    // =================================================
    // FIRST PASSENGER
    // =================================================

    const firstPassenger =
      passengerList[0];


    const firstPassengerName =
      `${firstPassenger.firstName || ""} ${firstPassenger.lastName || ""}`.trim();


    // =================================================
    // BOOK EXACT ADMIN TICKET / PNR
    // =================================================
    //
    // IMPORTANT:
    //
    // Payment gate already ran above.
    //
    // Admin:
    //   payment not required
    //
    // Agent/Customer:
    //   paymentVerified must be true
    //
    // Therefore PNR is booked only after the
    // required payment condition has passed.
    //

    const updatedFlight =
      await Flight.findOneAndUpdate(

        {
          _id:
            dbFlight._id,

          tickets: {
            $elemMatch: {

              pnr:
                selectedPNR,

              status:
                "Available",

            },
          },

        },

        {
          $set: {

            "tickets.$.status":
              "Booked",

            "tickets.$.bookingId":
              bookingId,

            "tickets.$.passengerName":
              firstPassengerName,

            "tickets.$.bookedAt":
              new Date(),

          },
        },

        {
          new: true,
        }

      );


    // =================================================
    // TICKET ALREADY BOOKED
    // =================================================

    if (!updatedFlight) {

      return res.status(409).json({

        success: false,

        message:
          "This ticket was just booked. Please try again.",

      });

    }


    bookedFlightId =
      dbFlight._id;


    bookedPNR =
      selectedPNR;


    // =================================================
    // FLIGHT SNAPSHOT
    // =================================================

    const flightSnapshot = {

      flightId:
        dbFlight._id,

      airline:
        dbFlight.airline || "",

      flightNo:
        dbFlight.flightNo || "",

      flightType:
        dbFlight.flightType ||
        "Domestic",

      aircraft:
        dbFlight.aircraft || "",


      // -----------------------------------------------
      // ROUTE
      // -----------------------------------------------

      fromCity:
        dbFlight.fromCity || "",

      fromAirport:
        dbFlight.fromAirport || "",

      fromCode:
        dbFlight.fromCode || "",

      toCity:
        dbFlight.toCity || "",

      toAirport:
        dbFlight.toAirport || "",

      toCode:
        dbFlight.toCode || "",


      // -----------------------------------------------
      // DEPARTURE
      // -----------------------------------------------

      departureDate:
        dbFlight.departureDate || "",

      departureTime:
        dbFlight.departureTime || "",

      departureTerminal:
        dbFlight.departureTerminal || "",


      // -----------------------------------------------
      // ARRIVAL
      // -----------------------------------------------

      arrivalDate:
        dbFlight.arrivalDate || "",

      arrivalTime:
        dbFlight.arrivalTime || "",

      arrivalTerminal:
        dbFlight.arrivalTerminal || "",


      // -----------------------------------------------
      // DETAILS
      // -----------------------------------------------

      duration:
        dbFlight.duration || "",

      stops:
        dbFlight.stops ||
        "Non-stop",

      stopAirport:
        dbFlight.stopAirport || "",


      // -----------------------------------------------
      // ACTUAL PRICE
      // -----------------------------------------------

      price:
        selectedAdultFare,

      finalPrice:
        selectedAdultFare,

      adultFare:
        selectedAdultFare,

      childFare:
        selectedChildFare,

      infantFare:
        selectedInfantFare,

      fareRole:
        normalizedFareRole,


      // -----------------------------------------------
      // LOGO
      // -----------------------------------------------

      logo:
        dbFlight.logo || "",

    };


    // =================================================
    // FINAL PAYMENT STATUS
    // =================================================

    const finalPaymentStatus =
      isAdmin || verifiedPayment
        ? "Paid"
        : "Pending";


    // =================================================
    // FINAL BOOKING STATUS
    // =================================================

    const finalBookingStatus =
      isAdmin || verifiedPayment
        ? "Confirmed"
        : "Pending";


    // =================================================
    // CREATE BOOKING
    // =================================================

    const booking =
      await Booking.create({

        // ---------------------------------------------
        // BOOKING ID
        // ---------------------------------------------

        bookingId:
          bookingId,


        // ---------------------------------------------
        // PNR
        // ---------------------------------------------

        pnr:
          selectedPNR,


        // ---------------------------------------------
        // FLIGHT ID
        // ---------------------------------------------

        flightId:
          dbFlight._id,


        // ---------------------------------------------
        // USER ROLE
        // ---------------------------------------------

        userRole:
          normalizedUserRole,


        // ---------------------------------------------
        // PASSENGER COUNTS
        // ---------------------------------------------

        adults:
          adultCount,

        children:
          childCount,

        infants:
          infantCount,

        totalPassengers:
          totalPassengerCount,


        // ---------------------------------------------
        // MULTIPLE PASSENGERS
        // ---------------------------------------------

        passengers:
          passengerList,


        // ---------------------------------------------
        // FLIGHT SNAPSHOT
        // ---------------------------------------------

        flight:
          flightSnapshot,


        // ---------------------------------------------
        // SEATS
        // ---------------------------------------------

        seats:
          normalizedSeats,

        seat:
          normalizedSeats[0]?.seatNumber ||
          seat ||
          "",

        seatPrice:
          finalSeatFare,


        // ---------------------------------------------
        // MEALS
        // ---------------------------------------------

        meals:
          normalizedMeals,

        meal: {

          name:
            normalizedMeals[0]?.name ||
            "No Meal",

          price:
            mealFare,

        },


        // ---------------------------------------------
        // BAGGAGE
        // ---------------------------------------------

        baggages:
          normalizedBaggages,

        baggage: {

          weight:
            normalizedBaggages[0]?.weight ||
            "15 KG (Included)",

          price:
            baggageFare,

        },


        // ---------------------------------------------
        // FARE BREAKDOWN
        // ---------------------------------------------

        flightFare:
          flightFare,

        adultFare:
          selectedAdultFare,

        childFare:
          selectedChildFare,

        infantFare:
          selectedInfantFare,

        fareRole:
          normalizedFareRole,

        seatFare:
          finalSeatFare,

        mealFare:
          mealFare,

        baggageFare:
          baggageFare,


        // ---------------------------------------------
        // PAYMENT
        // ---------------------------------------------

        paymentMethod:
          isAdmin
            ? "admin"
            : (
                paymentMethod ||
                "upi"
              ),

        paymentStatus:
          finalPaymentStatus,

        bookingStatus:
          finalBookingStatus,

// yhaaaaaa
paymentId:
  paymentId || "",

orderId:
  orderId || "",
          


        // ---------------------------------------------
        // OTHER CHARGES
        // ---------------------------------------------

        discount:
          discountAmount,

        taxes:
          taxes,

        convenienceFee:
          convenienceFee,


        // ---------------------------------------------
        // FINAL TOTAL
        // ---------------------------------------------

        total:
          calculatedTotal,

      });


    // =================================================
    // SUCCESS LOG
    // =================================================

    console.log(
      "========================================"
    );

    console.log(
      "BOOKING CREATED SUCCESSFULLY"
    );

    console.log(
      "Booking ID:",
      booking.bookingId
    );

    console.log(
      "PNR:",
      booking.pnr
    );

    console.log(
      "Flight ID:",
      booking.flightId
    );

    console.log(
      "Role:",
      normalizedUserRole
    );

    console.log(
      "Payment:",
      finalPaymentStatus
    );

    console.log(
      "Booking:",
      finalBookingStatus
    );

    console.log(
      "FINAL TOTAL:",
      booking.total
    );

    console.log(
      "========================================"
    );


    // =================================================
    // RESPONSE
    // =================================================

    return res.status(201).json({

      success: true,

      message:
        isAdmin
          ? "Admin booking confirmed successfully."
          : "Payment verified and booking confirmed successfully.",

      booking,

      userRole:
        normalizedUserRole,

      paymentRequired:
        !isAdmin,

      paymentVerified:
        isAdmin || verifiedPayment,

    });


  } catch (error) {

    console.error(
      "========================================"
    );

    console.error(
      "CREATE BOOKING ERROR:",
      error
    );

    console.error(
      "========================================"
    );


    // =================================================
    // ROLLBACK PNR
    // =================================================
    //
    // Agar ticket Booked ho gaya aur Booking.create
    // fail ho gaya, PNR ko Available kar denge.
    //

    if (
      bookedFlightId &&
      bookedPNR &&
      generatedBookingId
    ) {

      try {

        await Flight.updateOne(

          {
            _id:
              bookedFlightId,

            tickets: {
              $elemMatch: {

                pnr:
                  bookedPNR,

                bookingId:
                  generatedBookingId,

              },
            },

          },

          {
            $set: {

              "tickets.$.status":
                "Available",

              "tickets.$.bookingId":
                "",

              "tickets.$.passengerName":
                "",

              "tickets.$.bookedAt":
                null,

            },
          }

        );


        console.log(
          "PNR ROLLBACK SUCCESS:",
          bookedPNR
        );


      } catch (
        rollbackError
      ) {

        console.error(
          "PNR ROLLBACK ERROR:",
          rollbackError
        );

      }

    }


    // =================================================
    // ERROR RESPONSE
    // =================================================

    return res.status(500).json({

      success: false,

      message:
        error.message ||
        "Unable to create booking.",

    });

  }

};


// =====================================================
// GET ALL BOOKINGS
// GET /api/bookings
// =====================================================

const getAllBookings = async (
  req,
  res
) => {

  try {

    const bookings =
      await Booking.find()
        .sort({
          createdAt: -1,
        });


    return res.status(200).json({

      success: true,

      count:
        bookings.length,

      bookings,

    });


  } catch (error) {

    console.error(
      "GET BOOKINGS ERROR:",
      error
    );


    return res.status(500).json({

      success: false,

      message:
        error.message ||
        "Unable to fetch bookings.",

    });

  }

};


// =====================================================
// GET SINGLE BOOKING
// GET /api/bookings/:id
// =====================================================

const getBookingById = async (
  req,
  res
) => {

  try {

    const booking =
      await Booking.findById(
        req.params.id
      );


    if (!booking) {

      return res.status(404).json({

        success: false,

        message:
          "Booking not found.",

      });

    }


    return res.status(200).json({

      success: true,

      booking,

    });


  } catch (error) {

    console.error(
      "GET SINGLE BOOKING ERROR:",
      error
    );


    return res.status(500).json({

      success: false,

      message:
        error.message ||
        "Unable to fetch booking.",

    });

  }

};


// =====================================================
// DELETE BOOKING
// DELETE /api/bookings/:id
// =====================================================

const deleteBooking = async (
  req,
  res
) => {

  try {

    const booking =
      await Booking.findByIdAndDelete(
        req.params.id
      );


    if (!booking) {

      return res.status(404).json({

        success: false,

        message:
          "Booking not found.",

      });

    }


    return res.status(200).json({

      success: true,

      message:
        "Booking deleted successfully.",

    });


  } catch (error) {

    console.error(
      "DELETE BOOKING ERROR:",
      error
    );


    return res.status(500).json({

      success: false,

      message:
        error.message ||
        "Unable to delete booking.",

    });

  }

};


