// =====================================================
// CUSTOMER - MY BOOKINGS
// =====================================================

const getMyBookings = async (req, res) => {
  try {
    const userId =
      req.user?._id ||
      req.user?.id ||
      req.query.userId ||
      req.body?.userId ||
      req.headers["x-user-id"];

    if (!userId) {
      return res.status(401).json({
        success: false,
        message: "User login required",
      });
    }

    const bookings = await Booking.find({
      userId: userId,
    }).sort({ createdAt: -1 });

    return res.status(200).json({
      success: true,
      count: bookings.length,
      bookings,
    });
  } catch (error) {
    console.error("getMyBookings:", error);

    return res.status(500).json({
      success: false,
      message: error.message || "Unable to fetch bookings",
    });
  }
};


// =====================================================
// CUSTOMER - BOOKING BY PNR
// =====================================================

const getMyBookingByPNR = async (req, res) => {
  try {
    const userId =
      req.user?._id ||
      req.user?.id ||
      req.query.userId ||
      req.body?.userId ||
      req.headers["x-user-id"];

    const pnr = String(req.params.pnr || "")
      .trim()
      .toUpperCase();

    if (!userId) {
      return res.status(401).json({
        success: false,
        message: "User login required",
      });
    }

    if (!pnr) {
      return res.status(400).json({
        success: false,
        message: "PNR is required",
      });
    }

    const booking = await Booking.findOne({
      userId: userId,
      pnr: pnr,
    });

    if (!booking) {
      return res.status(404).json({
        success: false,
        message: "Booking not found",
      });
    }

    return res.status(200).json({
      success: true,
      booking,
    });
  } catch (error) {
    console.error("getMyBookingByPNR:", error);

    return res.status(500).json({
      success: false,
      message: error.message || "Unable to fetch booking",
    });
  }
};


// =====================================================
// CUSTOMER - SINGLE BOOKING
// =====================================================

const checkMyBooking = async (req, res) => {
  try {
    const userId =
      req.user?._id ||
      req.user?.id ||
      req.query.userId ||
      req.body?.userId ||
      req.headers["x-user-id"];

    const bookingId = req.params.bookingId;

    if (!userId) {
      return res.status(401).json({
        success: false,
        message: "User login required",
      });
    }

    if (!bookingId) {
      return res.status(400).json({
        success: false,
        message: "Booking ID is required",
      });
    }

    const booking = await Booking.findOne({
      _id: bookingId,
      userId: userId,
    });

    if (!booking) {
      return res.status(404).json({
        success: false,
        message: "Booking not found",
      });
    }

    return res.status(200).json({
      success: true,
      booking,
    });
  } catch (error) {
    console.error("checkMyBooking:", error);

    return res.status(500).json({
      success: false,
      message: error.message || "Unable to fetch booking",
    });
  }
};


